{"path": "units/csvfix/impl.py", "content": "import csv


def parse(line):
    """把一行 CSV 解析成恰好 3 个字段的列表。

    - 支持双引号包裹的字段（字段内部可以包含逗号）。
    - 每个字段两侧的空白会被裁剪。
    - 字段数不是 3 时返回 None（不抛异常）。
    """
    if not isinstance(line, str):
        return None
    try:
        row = next(csv.reader([line]))
    except (csv.Error, StopIteration):
        return None
    fields = [field.strip() for field in row]
    if len(fields) != 3:
        return None
    return fields


def total(rows):
    """求和每行的金额（金额 = 数量 * 单价）。

    rows 中每行形如 [id, qty, price]（parse 的输出，均为字符串）。
    - 单价为空白（""）的行视为无金额，跳过。
    - 单价非空但不能解析成整数的行抛 ValueError（不再静默当作 0）。
    - 行长度不足 3 时跳过。
    """
    result = 0
    for row in rows:
        if len(row) < 3:
            continue
        price_text = str(row[2]).strip()
        if price_text == "":
            continue
        try:
            qty = int(str(row[1]).strip())
            price = int(price_text)
        except ValueError as exc:
            raise ValueError("non-integer quantity/price in row %r" % (row,)) from exc
        result += qty * price
    return result
"}

{"path": "units/rules/engine.py", "content": "def evaluate(rules, facts):
    """按规则求值。

    - ``{"all": [key, ...]}``：所有 key 在 facts 中为真才为 True。
    - ``{"any": [key, ...]}``：任一 key 在 facts 中为真即为 True。
    - 缺失的 key 视为假；无法识别的规则返回 False。
    """
    if not isinstance(rules, dict):
        return False
    if "all" in rules:
        return all(bool(facts.get(key, False)) for key in rules["all"])
    if "any" in rules:
        return any(bool(facts.get(key, False)) for key in rules["any"])
    return False
"}

{"path": "units/ledger/ledger.py", "content": """"一个只关心单个账户的小账本。"""

_KINDS = ("deposit", "withdraw")


class Ledger:
    def apply(self, rows, op):
        """rows 是 [(kind, account, cents), ...]，返回**该账户**的行（保持原顺序）。

        - ``op`` 是要筛选的账户名。
        - kind 只有 "deposit" 与 "withdraw"，其它 kind 抛 ValueError。
        - 金额为负时抛 ValueError。
        """
        result = []
        for row in rows:
            kind, account, cents = row
            if kind not in _KINDS:
                raise ValueError("unknown kind: %r" % (kind,))
            if cents < 0:
                raise ValueError("negative amount: %r" % (cents,))
            if account == op:
                result.append((kind, account, cents))
        return result


def balance(rows, account):
    """返回该账户的净额：deposit 相加、withdraw 相减；没有该账户的行时返回 0。"""
    total = 0
    for kind, acct, cents in rows:
        if acct != account:
            continue
        if kind == "deposit":
            total += cents
        elif kind == "withdraw":
            total -= cents
        else:
            raise ValueError("unknown kind: %r" % (kind,))
    return total
"}

{"path": "units/schedule/schedule.py", "content": """"闭区间的时间段工具。"""


def slots(ranges, minutes):
    """合并闭区间：两段之间的空隙（next_lo - prev_hi）小于 minutes 视为同一段。

    返回按起点升序的合并结果；空输入返回 []。
    """
    if not ranges:
        return []
    ordered = sorted((tuple(r) for r in ranges), key=lambda r: (r[0], r[1]))
    merged = [list(ordered[0])]
    for lo, hi in ordered[1:]:
        if lo - merged[-1][1] < minutes:
            merged[-1][1] = max(merged[-1][1], hi)
        else:
            merged.append([lo, hi])
    return [tuple(seg) for seg in merged]


def overlaps(a, b):
    """两个闭区间是否有交叠；端点正好相接（如 (0,10) 与 (10,20)）不算交叠。"""
    return a[0] < b[1] and b[0] < a[1]
